package com.aoo.bcg.share;
import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import java.sql.*;import java.time.*;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class InviteLinkServiceTest{JdbcDataSource ds;JdbcInviteLinkRepository repo;InviteLinkSigner signer;@BeforeEach void setup()throws Exception{ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:invite;MODE=MySQL;DB_CLOSE_DELAY=-1");try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE aoo_hall_room(room_id BIGINT PRIMARY KEY,game_id BIGINT,classification_region_code VARCHAR(20),play_version VARCHAR(20),owner_account_id BIGINT,state VARCHAR(20))");s.execute("CREATE TABLE aoo_club_state(club_id BIGINT PRIMARY KEY)");s.execute("CREATE TABLE aoo_invite_link(invite_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,token_hash BINARY(32) UNIQUE,kind VARCHAR(8),target_id BIGINT,issuer_account_id BIGINT,max_uses INT,use_count INT,expires_at TIMESTAMP,status VARCHAR(16),created_at TIMESTAMP,last_used_at TIMESTAMP,revoked_at TIMESTAMP)");s.execute("CREATE TABLE aoo_invite_link_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,invite_id BIGINT,event_type VARCHAR(16),actor_account_id BIGINT,source_channel VARCHAR(64),source_hash BINARY(32),outcome VARCHAR(16),occurred_at TIMESTAMP)");s.execute("CREATE TABLE aoo_invite_consumption(consumption_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,idempotency_key VARCHAR(128) UNIQUE,invite_id BIGINT,consumer_account_id BIGINT,reward_state VARCHAR(16),reward_reference VARCHAR(160),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(invite_id,consumer_account_id))");s.execute("INSERT INTO aoo_hall_room VALUES(7,101,'cn','v2',42,'OPEN')");}repo=new JdbcInviteLinkRepository(ds,Clock.fixed(Instant.parse("2026-08-24T00:00:00Z"),ZoneOffset.UTC));signer=new InviteLinkSigner("01234567890123456789012345678901");}
@Test void previewDoesNotSpendAndAuthenticatedConsumeIsIdempotent()throws Exception{String token=signer.issue();repo.create(42,"ROOM",7,Duration.ofMinutes(5),1,token,"wechat");Map<String,Object>preview=repo.preview(signer.verify(token),"wechat","127.0.0.1","x");assertEquals(7L,preview.get("targetId"));var first=repo.consume(signer.verify(token),77,"consume-key-0001","wechat");var repeated=repo.consume(signer.verify(token),77,"consume-key-0001","wechat");assertEquals(first.consumptionId(),repeated.consumptionId());assertEquals("GRANTED",repo.rewarded(first.consumptionId(),"reward:1").rewardState());assertThrows(InviteLinkError.class,()->repo.consume(signer.verify(token),78,"consume-key-0002","direct"));try(Connection c=ds.getConnection();ResultSet r=c.createStatement().executeQuery("SELECT use_count,status FROM aoo_invite_link")){r.next();assertEquals(1,r.getInt(1));assertEquals("EXHAUSTED",r.getString(2));}}
@Test void revokeAndSignatureTamperingAreRejected(){String token=signer.issue();long id=((Number)repo.create(42,"ROOM",7,Duration.ofMinutes(5),3,token,"direct").get("inviteId")).longValue();repo.revoke(42,id,"direct");assertThrows(InviteLinkError.class,()->repo.preview(signer.verify(token),"direct","x","x"));String changed=token.substring(0,token.length()-1)+(token.endsWith("A")?"B":"A");assertThrows(InviteLinkError.class,()->signer.verify(changed));}
@Test void nonOwnerCannotIssueRoomInvite(){String token=signer.issue();assertThrows(InviteLinkError.class,()->repo.create(9,"ROOM",7,Duration.ofMinutes(5),1,token,"direct"));}}
